        for col in range(n):
            pivot_row = -1
            for row in range(rank, m):
                if A[row][col] != 0:
                    pivot_row = row
                    break
            if pivot_row == -1:
                continue
            A[pivot_row], A[rank] = A[rank], A[pivot_row]
            rank += 1
            for row in range(rank, m):
                factor = A[row][col] / A[pivot_row][col]
                for j in range(n):
                    A[row][j] -= factor * A[pivot_row][j]
        return rank

    return gaussian_elimination(matrix)

