        for j in range(i+1, n):
            factor = A[j][i] / A[i][i]
            for k in range(n):
                A[j][k] -= factor * A[i][k]
    return A

def spectral_norm(M):
    n = len(M)
    v = [random.random() for _ in range(n)]
    v /= math.sqrt(sum(x**2 for x in v))
    for _ in range(100):  # Power iteration
        v = [sum(M[i][j] * v[j] for j in range(n)) for i in range(n)]
        v /= math.sqrt(sum(x**2 for x in v))
    return max(abs(v))

def run_trial(seed: int) -> dict:
