def generate_bipartite_graph(n):
    A = list(range(n))
    B = list(range(n, 2*n))
    E = set()
    for _ in range(int(n * (n - 1) / 4)):
        u = random.choice(A)
        v = random.choice(B)
        if (u, v) not in E and (v, u) not in E:
            E.add((u, v))
    return A, B, E

def max_matching(G):
    n = len(G[0])
    matching = [-1] * n
    visited = [False] * n

    def dfs(u):
        for v in G[u]:
            if not visited[v]:
                visited[v] = True
                if matching[v] == -1 or dfs(matching[v]):
                    matching[v] = u
                    return True
        return False

    for u in range(n):
        visited = [False] * n
        dfs(u)

    return sum(1 for x in matching if x != -1)

