    matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            matrix[i][j] = 1
            matrix[j][i] = 1
    return matrix

def tensor_product(t1, t2):
    result = []
    for a in t1:
        row = []
        for b in t2:
            row.extend([x * y for x, y in zip(a, b)])
        result.append(row)
    return result

