    n = len(tensor)
    U = [[0] * n for _ in range(n)]
    V = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if tensor[i][j] != 0:
                U[i][i] = 1
                V[j][j] = 1
