def hook_length_formula(row):
    n = len(row)
    numerator = factorial(factorial(n))
    denominator = 1
    for cell in range(len(row)):
        row_length = row[cell]
        col_length = sum(1 for r in row if r > cell)
        denominator *= (row_length + col_length) * (cell + 1)
    return numerator // denominator

