import random
import math

def generate_read_twice_bp(n):
    bp = []
    for _ in range(2**n):
        path = [random.choice([0, 1]) for _ in range(n)]
        bp.append(path)
    return bp

def count_paths(bp, i, j):
    count = 0
    for path in bp:
        if path[i] == j and path[j] == j:
            count += 1
    return count

def generate_transition_matrix(bp, n):
    M_P = [[count_paths(bp, i, j) for j in range(2)] for i in range(n)]
    return M_P

def r_transform(M, samples=1000):
    n = len(M)
    R = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for _ in range(samples):
                x = random.uniform(0, 1)
                y = random.uniform(0, 1)
                if M[i][j] > 0:
                    R[i][j] += (x - 1) / M[i][j]
    return R

def free_entropy(R):
    n = len(R)
    trace = sum(R[i][i] for i in range(n))
    det = 1
    for i in range(n):
        det *= R[i][i]
    return trace - math.log(det)

def run_trial(seed: int) -> dict:
    random.seed(seed)
    n_values = [5, 10, 15, 20, 30, 40]
    results = []

    for n in n_values:
        bp = generate_read_twice_bp(n)
        M_P = generate_transition_matrix(bp, n)
        R = r_transform(M_P)
        φ_M_P = free_entropy(R)

        size_P = len(bp)
        conjecture_holds = φ_M_P <= math.log(size_P) + 5 * math.sqrt(n)
        counterexample = "" if conjecture_holds else "n={}".format(n)

        results.append({
            "metric_name": "free_entropy",
            "metric_value": φ_M_P,
            "instances_tested": 1,
            "conjecture_holds": conjecture_holds,
            "counterexample": counterexample
        })

    return {
        "seed": seed,
        "results": results
    }

if __name__ == "__main__":
    import sys
    seeds = [int(s) for s in sys.argv[1:]] or [2**i - 1 for i in range(5, 30)]

    all_results = []
    for seed in seeds:
        result = run_trial(seed)
        print("TRIAL:", result)
        all_results.extend(result["results"])

    mean_value = sum(r["metric_value"] for r in all_results) / len(all_results)
    std_value = math.sqrt(sum((r["metric_value"] - mean_value)**2 for r in all_results) / len(all_results))
    support_fraction = sum(1 for r in all_results if r["conjecture_holds"]) / len(all_results)

    if support_fraction >= 0.8:
        print("RESULT: SUPPORTED mean={} std={} support_fraction={}".format(mean_value, std_value, support_fraction))
    elif any(not r["conjecture_holds"] for r in all_results):
        first_failing_seed = next(r["seed"] for r in all_results if not r["conjecture_holds"])
        print("RESULT: FALSIFIED counterexample=\"n={}\" first_failing_seed={}".format(first_failing_seed, first_failing_seed))
    else:
        print("RESULT: INCONCLUSIVE insufficient data")

import random
import math
from collections import defaultdict

def generate_expander_graph(n, m):
    graph = [[] for _ in range(n)]
    edges_added = 0
    while edges_added < m:
        u, v = random.sample(range(n), 2)
        if u != v and v not in graph[u]:
            graph[u].append(v)
            graph[v].append(u)
            edges_added += 1
    return graph

def find_fundamental_group_rank(graph):
    n = len(graph)
    visited = [False] * n
    rank = 0

    def dfs(node, parent):
        nonlocal rank
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, node)
            elif neighbor != parent:
                rank += 1

    for i in range(n):
        if not visited[i]:
            dfs(i, -1)

    return rank

def generate_tseitin_formula(graph):
    n = len(graph)
    literals = [f'x{i}' for i in range(n)]
    clauses = []

    # Add clauses for each edge
    for u, v in [(i, j) for i in range(n) for j in graph[i]]:
        clauses.append([f'-{literals[u]}', f'{literals[v]}'])
        clauses.append([f'{literals[u]}', f'-{literals[v]}'])

    # Add clauses to ensure each literal appears exactly once
    for i in range(n):
        clauses.append([f'{literals[i]}'])
        clauses.append([f'-{literals[i]}'])

    return literals, clauses

def dpll_with_clause_learning(clauses, literals):
    def is_satisfiable():
        assignment = {}

        def backtrack(level):
            if level == len(literals):
                return True
            literal = literals[level]
            for value in [True, False]:
                assignment[literal] = value
                if all([not clause or any(assignment.get(lit, not value) for lit in clause) for clause in clauses]):
                    if backtrack(level + 1):
                        return True
            del assignment[literal]
            return False

        return backtrack(0)

    return is_satisfiable()

def run_trial(seed: int) -> dict:
    random.seed(seed)
    n = random.randint(5, 40)
    m = int(1.5 * n)
    graph = generate_expander_graph(n, m)
    rank = find_fundamental_group_rank(graph)
    literals, clauses = generate_tseitin_formula(graph)

    proof_size = dpll_with_clause_learning(clauses, literals)

    if not proof_size:
        return {
            "metric_name": "resolution_proof_size",
            "metric_value": 0,
            "instances_tested": 1,
            "conjecture_holds": False,
            "counterexample": "DPLL did not find a proof"
        }

    c = 0.3
    expected_size = 2 ** (c * (m - n + 1))

    return {
        "metric_name": "resolution_proof_size",
        "metric_value": proof_size,
        "instances_tested": 1,
        "conjecture_holds": proof_size >= expected_size,
        "counterexample": ""
    }

if __name__ == "__main__":
    import sys
    seeds = [int(x) for x in sys.argv[1:]] or list(range(2, 230, 7))  # Default to first 30 primes if no seeds provided

    results = []
    for seed in seeds:
        result = run_trial(seed)
        print(f"TRIAL: {{\"seed\": {seed}, \"metric_name\": \"{result['metric_name']}\", \"metric_value\": {result['metric_value']}, \"instances_tested\": {result['instances_tested']}, \"conjecture_holds\": {result['conjecture_holds']}, \"counterexample\": \"{result['counterexample']}\"}}")
        results.append(result)

    mean = sum(r['metric_value'] for r in results) / len(results)
    std_dev = math.sqrt(sum((r['metric_value'] - mean) ** 2 for r in results) / len(results))
    support_fraction = sum(1 for r in results if r['conjecture_holds']) / len(results)

    if all(r['conjecture_holds'] for r in results):
        print(f"RESULT: SUPPORTED mean={mean} std={std_dev} support_fraction={support_fraction}")
    elif support_fraction >= 0.8:
        print(f"RESULT: SUPPORTED mean={mean} std={std_dev} support_fraction={support_fraction}")
    else:
        first_failing_seed = next((r['seed'] for r in results if not r['conjecture_holds']), None)
        print(f"RESULT: FALSIFIED counterexample=\"\" first_failing_seed={first_failing_seed}")

