import random
import math

def generate_disjointness_matrix(n):
    M = [[0] * n for _ in range(n)]
    for i in range(n):
        M[i][i + 1 if i < n - 1 else 0] = 1
        M[(i + 2) % n][(i + 3) % n] = 1
    return M

def matrix_multiply(A, B):
    m, k, n = len(A), len(B[0]), len(B)
    C = [[0] * n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            for l in range(k):
                C[i][j] += A[i][l] * B[l][j]
    return C

def transpose(M):
    m, n = len(M), len(M[0])
    M_t = [[0] * m for _ in range(n)]
    for i in range(m):
        for j in range(n):
            M_t[j][i] = M[i][j]
    return M_t

def is_symplectic_form(M, n):
    I = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    return matrix_multiply(matrix_multiply(M, M), I) == -I and matrix_multiply(transpose(M), M) == -I

def symplectic_rank(M, n):
    rank = 0
    while True:
        found = False
        for i in range(n):
            for j in range(i + 1, n):
                if M[i][j] != 0:
                    found = True
                    break
            if found:
                break
        if not found:
            return rank
        rank += 1
        for i in range(n):
            for j in range(n):
                M[i][j] -= M[i][j] * M[j][i]

def run_trial(seed: int) -> dict:
    random.seed(seed)
    n_values = [5, 10, 15, 20, 30, 40]
    c = 0.25
    instances_tested = 0
    conjecture_holds = True
    counterexample = ""

