import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_random_graph(n):
        graph = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(i + 1, n):
                if random.random() < 0.5:
                    graph[i][j] = 1
                    graph[j][i] = 1
        return graph

    def find_max_disjoint_cliques(graph, k):
        n = len(graph)
        visited = [False] * n
        max_cliques = []

        def dfs(node, clique):
            if len(clique) == k:
                max_cliques.append(clique[:])
                return True
            for neighbor in range(n):
                if graph[node][neighbor] and not visited[neighbor]:
                    visited[neighbor] = True
                    if dfs(neighbor, clique + [neighbor]):
                        visited[neighbor] = False
                        return True
                    visited[neighbor] = False
            return False

        for i in range(n):
            if not visited[i]:
                visited[i] = True
                dfs(i, [i])
                visited[i] = False

        return max_cliques

    def estimate_dnf_size(cliques):
        return len(cliques)

    n = 40
    k = 3
    graph = generate_random_graph(n)
    cliques = find_max_disjoint_cliques(graph, k)
    r = len(cliques)
    dnf_size = estimate_dnf_size(cliques)

    if r == 0:
        return {
            "metric_name": "dnf_size",
            "metric_value": float('inf'),
            "instances_tested": 1,
            "conjecture_holds": False,
            "counterexample": "no_disjoint_cliques"
