    for i in range(n):
        for j in range(n):
            for k in range(n):
                result[i][j] += a[i][k] * b[k][j]
    return result

def matrix_trace(m):
    n = len(m)
    trace = 0
    for i in range(n):
        trace += m[i][i]
    return trace

def burau_generator(n, k, exponent):
    matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        if i == k:
            matrix[i][i] = 1
        elif i == k + 1:
            matrix[i][i] = -1
            matrix[i][k] = exponent
        else:
            matrix[i][i] = 1
    return matrix

def generate_3cnf(n, m, seed):
    random.seed(seed)
    variables = list(range(1, n + 1))
    clauses = []
    for _ in range(m):
        clause_vars = random.sample(variables, 3)
        clause = []
        for var in clause_vars:
            if random.random() < 0.5:
                clause.append(-var)
            else:
                clause.append(var)
        clauses.append(clause)
    return clauses

def is_unsat(clauses, n):
    assignments = [None] * (n + 1)
    for clause in clauses:
        for lit in clause:
            var = abs(lit)
            if assignments[var] is None:
                assignments[var] = lit > 0
            elif (assignments[var] and lit < 0) or (not assignments[var] and lit > 0):
                return False
    return True

def lex_dpll(clauses, n):
    assignments = [None] * (n + 1)
    backtracks = 0

    def backtrack(level):
        nonlocal backtracks
        if level == n + 1:
            return True
        var = level
        for val in [True, False]:
            assignments[var] = val
            if is_satisfiable(clauses, assignments):
                if backtrack(level + 1):
                    return True
            assignments[var] = None
            backtracks += 1
        return False

    def is_satisfiable(clauses, assignments):
        for clause in clauses:
            satisfied = False
            for lit in clause:
                var = abs(lit)
                if assignments[var] is not None:
                    if (assignments[var] and lit > 0) or (not assignments[var] and lit < 0):
                        satisfied = True
                        break
            if not satisfied:
                return False
        return True

    backtrack(1)
    return backtracks

def run_trial(seed):
