import sys
import random
import math
import itertools
from fractions import Fraction

def generate_3_regular_graph(n):
    if n % 2 != 0:
        raise ValueError("n must be even for a 3-regular graph")
    vertices = list(range(n))
    stubs = vertices * 3
    random.shuffle(stubs)
    edges = []
    while stubs:
        u = stubs.pop()
        if not stubs:
            break
        v = random.choice([s for s in stubs if s != u])
        stubs.remove(v)
        edges.append((u, v))
    return vertices, edges

def build_adjacency_matrix(vertices, edges):
    n = len(vertices)
    adj = [[0] * n for _ in range(n)]
    for u, v in edges:
        adj[u][v] = 1
        adj[v][u] = 1
    return adj

def matrix_multiply(A, B):
    n = len(A)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                result[i][j] += A[i][k] * B[k][j]
    return result

def matrix_subtract(A, B):
    n = len(A)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            result[i][j] = A[i][j] - B[i][j]
    return result

def matrix_vector_multiply(M, v):
    n = len(M)
    result = [0] * n
    for i in range(n):
        for j in range(n):
            result[i] += M[i][j] * v[j]
    return result

def vector_norm(v):
    return math.sqrt(sum(x**2 for x in v))

def power_iteration(A, max_iter=100, tol=1e-6):
    n = len(A)
    b = [random.random() for _ in range(n)]
    for _ in range(max_iter):
        b_new = matrix_vector_multiply(A, b)
        norm = vector_norm(b_new)
        if norm == 0:
            break
        b_new = [x / norm for x in b_new]
        if vector_norm([b_new[i] - b[i] for i in range(n)]) < tol:
            break
        b = b_new
    return norm

def compute_mu(adj, psi):
    n = len(adj)
    D = [[0] * n for _ in range(n)]
    for i in range(n):
        D[i][i] = sum(adj[i])
    A_sigma = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if adj[i][j] == 1:
                A_sigma[i][j] = (-1) ** psi[i][j]
    L_sigma = matrix_subtract(D, A_sigma)
    return power_iteration(L_sigma)

