    var_psi_f = sum(x**2 for x in psi_f_hat) - (sum(psi_f_hat))**2
    stab_rho = sum((1 - (1-1/n)**len(S)) * x**2 for S, x in enumerate(psi_f_hat))
    nsm = (var_psi_f - stab_rho) / var_psi_f if var_psi_f != 0 else 0
    return nsm

