            "metric_name": "log2_SC(f) - D(f)",
            "metric_value": 0,
            "instances_tested": 0,
            "conjecture_holds": False,
            "counterexample": "No instances tested"
        }

    mean_metric = sum(metric_values) / len(metric_values)
    return {
        "metric_name": "log2_SC(f) - D(f)",
        "metric_value": mean_metric,
        "instances_tested": instances_tested,
