        cols_A = len(A[0])
        cols_B = len(B[0])
        result = [[sum(A[i][k] * B[k][j] for k in range(cols_A)) for j in range(cols_B)] for i in range(rows_A)]
        return result

    def gaussian_elimination(M):
        rows, cols = len(M), len(M[0])
        for i in range(rows):
