import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_3cnf(n, m):
        clauses = set()
        variables = list(range(1, n + 1))
        for _ in range(m):
            clause = []
            for _ in range(3):
                var = random.choice(variables)
                polarity = random.choice([-1, 1])
                clause.append((var, polarity))
            clauses.add(tuple(sorted(clause)))
        return clauses

    def is_unsat(cnf):
        # Simple DPLL algorithm to check unsatisfiability
        assignment = [None] * (n + 1)

        def dpll():
            stack = []
            for var in range(1, n + 1):
                if all(any(abs(clause[var - 1][0]) == abs(var) and clause[var - 1][1] != polarity for clause in cnf) for polarity in [-1, 1]):
                    assignment[var] = 1
                    stack.append((var, 1))
                elif all(any(abs(clause[var - 1][0]) == abs(var) and clause[var - 1][1] != polarity for clause in cnf) for polarity in [1, -1]):
                    assignment[var] = -1
                    stack.append((var, -1))
                else:
                    return False
            while stack:
                var, polarity = stack.pop()
                if not all(any(abs(clause[var - 1][0]) == abs(var) and clause[var - 1][1] != polarity for clause in cnf) for polarity in [-1, 1]):
                    assignment[var] = -polarity
                    stack.append((var, -polarity))
            return True

        return not dpll()

    def walsh_hadamard_transform(cnf):
        n_vars = len(cnf)
        spectrum = [0] * (2 ** n_vars)

        for i in range(1 << n_vars):
            x = [1 if (i >> j) & 1 else -1 for j in range(n_vars)]
            value = sum(1 if all(x[var - 1] == polarity for var, polarity in clause) else -1 for clause in cnf)
            spectrum[i] = value / math.sqrt(len(cnf))

        return spectrum

    def spectral_entropy(spectrum):
        norm_squared = sum(abs(val) ** 2 for val in spectrum)
        entropy = 0
        for val in spectrum:
            if val != 0:
                q = abs(val) ** 2 / norm_squared
                entropy -= q * math.log2(q)
        return entropy

    def tree_resolution(cnf):
        # Simplified tree-resolution algorithm to count leaf nodes
        stack = []
        for var in range(1, n + 1):
            if all(any(abs(clause[var - 1][0]) == abs(var) and clause[var - 1][1] != polarity for clause in cnf) for polarity in [-1, 1]):
                assignment[var] = 1
                stack.append((var, 1))
            elif all(any(abs(clause[var - 1][0]) == abs(var) and clause[var - 1][1] != polarity for clause in cnf) for polarity in [1, -1]):
                assignment[var] = -1
                stack.append((var, -1))
            else:
                return len(cnf)

        while stack:
            var, polarity = stack.pop()
            if not all(any(abs(clause[var - 1][0]) == abs(var) and clause[var - 1][1] != polarity for clause in cnf) for polarity in [-1, 1]):
                assignment[var] = -polarity
                stack.append((var, -polarity))

        return len(cnf)

    n = random.randint(10, 20)
    m = math.ceil(4.3 * n)
    cnf = generate_3cnf(n, m)

    if not is_unsat(cnf):
        return {
            "metric_name": "R(F)",
            "metric_value": float('nan'),
            "instances_tested": 1,
            "conjecture_holds": False,
            "counterexample": "unsatisfiable_cnf"
        }

    spectrum = walsh_hadamard_transform(cnf)
    H_F = spectral_entropy(spectrum)
    t_star = tree_resolution(cnf)

    if H_F == 0:
        return {
            "metric_name": "R(F)",
            "metric_value": float('nan'),
            "instances_tested": 1,
            "conjecture_holds": False,
            "counterexample": "zero_entropy"
        }

    R_F = math.log2(t_star) * math.log2(1 + n + n**2 + n**3) / (n * H_F)

    return {
        "metric_name": "R(F)",
        "metric_value": R_F,
        "instances_tested": 1,
        "conjecture_holds": R_F >= 0.05,
        "counterexample": ""
    }

if __name__ == "__main__":
    seeds = [int(arg) for arg in sys.argv[1:]] or [2**i - 1 for i in range(3, 6)]  # Default to first 30 primes
    results = []

    for seed in seeds:
        trial = run_trial(seed)
        print(f"TRIAL: {trial}")
        results.append(trial)

    R_F_values = [result["metric_value"] for result in results if not math.isnan(result["metric_value"])]
    support_fraction = sum(1 for result in results if result["conjecture_holds"]) / len(results)

    if all(R_F >= 0.05 for R_F in R_F_values) and support_fraction >= 0.8:
        print(f"RESULT: SUPPORTED mean={sum(R_F_values)/len(R_F_values)} std={math.sqrt(sum((x - sum(R_F_values)/len(R_F_values))**2 for x in R_F_values)/len(R_F_values))} support_fraction={support_fraction}")
    elif any(result["conjecture_holds"] is False for result in results):
        first_failing_seed = next(seed for seed, result in zip(seeds, results) if not result["conjecture_holds"])
        print(f"RESULT: FALSIFIED counterexample=\"low_R_F\" first_failing_seed={first_failing_seed}")
    else:
        print("RESULT: INCONCLUSIVE insufficient_support")

import random
import math
from collections import defaultdict

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return abs(a*b) // gcd(a, b)

def matrix_mod(A, m):
    n = len(A)
    result = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            result[i][j] = (A[i][j] % m + m) % m
    return result

def matrix_multiply(A, B, m):
    n = len(A)
    result = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % m
    return result

def matrix_power(A, k, m):
    n = len(A)
    result = [[0]*n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    while k > 0:
        if k % 2 == 1:
            result = matrix_multiply(result, A, m)
        A = matrix_multiply(A, A, m)
        k //= 2
    return result

def linial_shraibman_gamma(M):
    n = len(M)
    M_T_M = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(i, n):
            sum_val = 0
            for k in range(n):
                sum_val += (M[i][k] * M[j][k]) % n
            M_T_M[i][j] = sum_val
            M_T_M[j][i] = sum_val

    eigenvalues = []
    for i in range(1, 20):  # Limit to 20 iterations for practical purposes
        v = [random.randint(0, n-1) for _ in range(n)]
        v_norm = sum(v[i]**2 for i in range(n)) ** 0.5
        v = [v[i] / v_norm for i in range(n)]
        for _ in range(i):
            v_next = [M_T_M[j][i] * v[j] for j in range(n)]
            v_next_norm = sum(v_next[j]**2 for j in range(n)) ** 0.5
            v_next = [v_next[i] / v_next_norm for i in range(n)]
        eigenvalues.append(sum(v_next[j]**2 for j in range(n)))

    return max(eigenvalues) / n

def is_sign_matrix(M):
    return all(x == 1 or x == -1 for row in M for x in row)

def det_mod_2k(M, k):
    n = len(M)
    A = matrix_mod(M, 2**k)
    for i in range(n):
        if A[i][i] == 0:
            for j in range(i+1, n):
                if A[j][i] != 0:
                    A[i], A[j] = A[j], A[i]
                    break
            else:
                return 0
        for j in range(n):
            if i != j:
                factor = (A[j][i] * pow(A[i][i], -1, 2**k)) % (2**k)
                for l in range(n):
                    A[j][l] = (A[j][l] - factor * A[i][l]) % (2**k)
    det = 1
    for i in range(n):
        det = (det * A[i][i]) % (2**k)
    return det

def v_2(x):
    if x == 0:
        return float('inf')
    count = 0
    while x % 2 == 0:
        x //= 2
        count += 1
    return count

