def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_disjointness_matrix(n):
        M = [[0] * n for _ in range(n)]
        for i in range(n):
            M[i][i] = 1
        return M

    def secant_rank(M):
        n = len(M)
        minors = []

        def determinant(matrix):
            if len(matrix) == 2:
                return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]
            det = 0
            for j in range(len(matrix)):
                submatrix = [row[:j] + row[j+1:] for row in matrix[1:]]
                det += (-1) ** j * matrix[0][j] * determinant(submatrix)
            return det

        def is_rank_1(M):
            if len(M) == 1 and len(M[0]) == 1:
                return True
            for i in range(len(M)):
                for j in range(len(M[i])):
                    if M[i][j] != 0:
                        submatrix = [row[:j] + row[j+1:] for row in M[:i] + M[i+1:]]
                        if determinant(submatrix) == 0:
                            return True
            return False

        def compute_minors(M):
            n = len(M)
            for i in range(n):
                for j in range(n):
                    submatrix = [row[:j] + row[j+1:] for row in M[:i] + M[i+1:]]
                    minors.append(determinant(submatrix))

        compute_minors(M)
        rank_1_tensors = 0
        for minor in minors:
            if is_rank_1([[minor]]):
                rank_1_tensors += 1

        return rank_1_tensors

    n_values = [5, 10, 15, 20, 30, 40]
    results = []

    for n in n_values:
        M = generate_disjointness_matrix(n)
        sr_M_n = secant_rank(M)
        results.append(sr_M_n)

        if sr_M_n < 0.8 * n:
            return {
                "metric_name": "secant_rank",
                "metric_value": sr_M_n,
                "instances_tested": len(results),
                "conjecture_holds": False,
                "counterexample": f"n={n}, sr(M_n)={sr_M_n}"
            }

    support_fraction = sum(1 for r in results if r >= 0.8 * n_values[-1]) / len(results)
    return {
        "metric_name": "secant_rank",
        "metric_value": sum(results) / len(results),
        "instances_tested": len(results),
        "conjecture_holds": support_fraction >= 0.8,
        "counterexample": ""
    }

