from fractions import Fraction

def gaussian_elimination(matrix):
    rows, cols = len(matrix), len(matrix[0])
    for i in range(rows):
        # Find pivot row
        max_row = i
        for r in range(i + 1, rows):
            if abs(matrix[r][i]) > abs(matrix[max_row][i]):
                max_row = r
        matrix[i], matrix[max_row] = matrix[max_row], matrix[i]

        # Eliminate below pivot
        pivot = matrix[i][i]
        if pivot == 0:
            continue
        for j in range(i, cols):
            matrix[i][j] /= pivot

        for r in range(rows):
            if r != i and matrix[r][i] != 0:
                factor = matrix[r][i]
                for j in range(i, cols):
                    matrix[r][j] -= factor * matrix[i][j]
    rank = sum(1 for row in matrix if any(val != 0 for val in row))
    return rank

def run_trial(seed: int) -> dict:
    random.seed(seed)
    n = random.randint(5, 40)

    def generate_bp(n):
        bp = []
        for i in range(n):
            bp.append(random.choice(['R', 'O']))
        return bp

    def is_read_once(bp):
        return all(x == 'O' for x in bp)

    def transition_matrix(bp):
        m = [[0] * n for _ in range(n)]
        for i in range(n):
            if bp[i] == 'R':
                j = random.randint(0, i - 1) if i > 0 else 0
                m[i][j] = 1
            elif bp[i] == 'O':
                j = random.randint(i + 1, n - 1)
                m[j][i] = 1
        return m

    def matroid_rank(matrix):
        return gaussian_elimination(matrix)

    read_once_count = 0
    total_rank = 0

    for _ in range(30):
