def generate_random_3_regular_graph(n):
    if n % 2 != 0 or n < 4:
        raise ValueError("n must be even and at least 4")

    G = [[] for _ in range(n)]
    edges = set()

    def add_edge(u, v):
        if (u, v) not in edges and (v, u) not in edges:
            G[u].append(v)
            G[v].append(u)
            edges.add((u, v))
            edges.add((v, u))

    for i in range(n):
        for j in range(i + 1, n):
            if len(G[i]) < 3 and len(G[j]) < 3:
                add_edge(i, j)

    return G

def tutte_polynomial(G, x, y):
