        nonlocal count
        visited[v] = True
        for u in G[v]:
            if not visited[u]:
                dfs(u, v)
        if parent is None:
            count += 1

    n = len(G)
    visited = [False] * n
    count = 0
    dfs(0, None)
    return Fraction(count)

