def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_max_cut_instance(n):
        edges = []
        for i in range(n):
            for j in range(i + 1, n):
                if random.random() < 0.5:
                    edges.append((i, j))
        return edges

    def construct_moment_matrix(edges, n):
        M = [[0] * n for _ in range(n)]
        for i, j in edges:
            M[i][j] += 1
            M[j][i] += 1
        return M

    def is_positive_semidefinite(M):
        n = len(M)
        for k in range(1, n + 1):
            submatrix = [row[:k] for row in M[:k]]
            det = determinant(submatrix)
            if det < 0:
                return False
        return True

    def determinant(matrix):
        n = len(matrix)
        if n == 1:
            return matrix[0][0]
        det = 0
        for j in range(n):
            submatrix = [row[:j] + row[j+1:] for row in matrix[1:]]
            det += (-1) ** j * matrix[0][j] * determinant(submatrix)
        return det

    def is_real_rooted(poly):
        n = len(poly)
        if n == 1:
            return poly[0] != 0
        for i in range(1, n):
            if poly[i].denominator != 1 or poly[i].numerator < 0:
                return False
        return True

    def find_real_stable_minor(M, d=2):
        n = len(M)
        minors = []
        for i in range(n - d + 1):
            for j in range(i, n - d + 1):
                minor = [row[j:j+d] for row in M[i:i+d]]
                if is_positive_semidefinite(minor) and is_real_rooted([Fraction(coeff, 1) for coeff in poly]):
                    minors.append(minor)
        return minors

    def sos_refutation_threshold(M):
        n = len(M)
        A = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n):
            for j in range(i, n):
                A[i][j] = M[i][j]
                A[j][i] = M[i][j]
        A[n][n] = 1
        b = [0] * (n + 1)
        b[n] = -1
        x = gaussian_elimination(A, b)
        return sum(x[:n])

    def gaussian_elimination(A, b):
        n = len(b)
        for i in range(n):
            max_row = i
            for j in range(i+1, n):
                if abs(A[j][i]) > abs(A[max_row][i]):
                    max_row = j
            A[i], A[max_row] = A[max_row], A[i]
            b[i], b[max_row] = b[max_row], b[i]
            for j in range(i+1, n):
                factor = A[j][i] / A[i][i]
                A[j][i] = 0
                for k in range(i+1, n+1):
                    A[j][k] -= factor * A[i][k]
                b[j] -= factor * b[i]
        x = [0] * n
        for i in range(n-1, -1, -1):
            x[i] = (b[i] - sum(A[i][j] * x[j] for j in range(i+1, n))) / A[i][i]
        return x

    def degree_2_moment_matrix(edges, n):
        M = [[0] * n for _ in range(n)]
        for i, j in edges:
            M[i][j] += 1
            M[j][i] += 1
        return M

    n = random.randint(5, 40)
    edges = generate_max_cut_instance(n)
    M = construct_moment_matrix(edges, n)

    minors = find_real_stable_minor(M, d=2)
    threshold = sos_refutation_threshold(degree_2_moment_matrix(edges, n))

