import random
import math

def factorial(n):
    if n == 0 or n == 1:
        return 1
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def binomial_coefficient(n, k):
    return factorial(n) // (factorial(k) * factorial(n - k))

def murnaghan_nakayama(lam, mu, beta):
    if len(mu) > len(lam):
        return 0
    sign = 1
    for i in range(len(mu)):
        sign *= (-1) ** (lam[i] - mu[i])
    result = binomial_coefficient(lam[0], mu[0])
    for i in range(1, len(lam)):
        if lam[i] < mu[i]:
            return 0
        result *= binomial_coefficient(lam[i] - mu[i], mu[i]) // binomial_coefficient(lam[i], mu[i])
    return sign * result

def irreducible_character(lam, beta):
    result = 1
    for i in range(len(beta)):
        result *= murnaghan_nakayama(lam, [beta[i]], beta)
    return result

def specht_coefficient(f, lam, chi_lam):
    return sum(c_f * chi_lam for c_f, sigma in f.items() if len(sigma) == len(lam))

def effective_specht_support(f, chi_table):
    numerator = 0
    denominator = 0
    for lam, dim_vlam in chi_table.items():
        alpha_lam = specht_coefficient(f, lam, chi_table[lam])
        numerator += dim_vlam * alpha_lam ** 2
        denominator += dim_vlam * alpha_lam ** 4
    return (numerator / denominator) ** 0.5

def generate_random_formula(n, s):
    if n < 1 or s < 1:
        raise ValueError("n and s must be at least 1")

    def is_disjoint(a, b):
        return not any(x in b for x in a)

    def generate_node():
        row_set = random.sample(range(n), random.randint(1, n))
        col_set = random.sample(range(n), random.randint(1, n))
        bijection = {i: j for i, j in zip(row_set, col_set)}
        weight = random.random()
        return (row_set, col_set, bijection, weight)

    def generate_tree(depth):
        if depth == 0:
            return generate_node()
        else:
            left = generate_tree(depth - 1)
            right = generate_tree(depth - 1)
            while not is_disjoint(left[0], right[0]) or not is_disjoint(left[1], right[1]):
                left = generate_tree(depth - 1)
                right = generate_tree(depth - 1)
            return ("⊗", left, right)

    tree = generate_tree(s - 1)

    def evaluate_tree(node):
        if isinstance(node, tuple) and node[0] == "⊗":
            left = evaluate_tree(node[1])
            right = evaluate_tree(node[2])
            result = {}
            for sigma in left:
                for tau in right:
                    new_sigma = sigma + tau
                    result[new_sigma] = (left[sigma] * right[tau]) if is_disjoint(sigma, tau) else 0
            return result
        else:
            row_set, col_set, bijection, weight = node
            result = {}
            for sigma in itertools.permutations(range(n)):
                if all(bijection[i] == sigma[j] for i, j in enumerate(row_set)):
                    result[sigma] = weight
            return result

    f = evaluate_tree(tree)

    chi_table = {lam: irreducible_character(lam, beta) for lam in itertools.combinations(range(n), n // 2)}

    return f, chi_table

def run_trial(seed: int) -> dict:
    random.seed(seed)
    results = []
    n_values = [4, 5, 6, 7]
    s_values = [1, 2, 4, 8, 16, 32]

    for n in n_values:
        for s in s_values:
            f, chi_table = generate_random_formula(n, s)
            supp_eff = effective_specht_support(f, chi_table)
            results.append({
                "n": n,
                "s": s,
                "supp_eff": supp_eff
            })

    mean_supp_eff = sum(result["supp_eff"] for result in results) / len(results)
    max_supp_eff = max(result["supp_eff"] for result in results)
    support_fraction = sum(1 for result in results if result["supp_eff"] <= result["s"]) / len(results)

    conjecture_holds = support_fraction >= 0.8 and mean_supp_eff <= 1 and max_supp_eff <= 1.05
    counterexample = "" if conjecture_holds else f"max(supp_eff)={max_supp_eff} > s"

    return {
        "metric_name": "effective_specht_support",
        "metric_value": mean_supp_eff,
        "instances_tested": len(results),
        "conjecture_holds": conjecture_holds,
        "counterexample": counterexample
    }

if __name__ == "__main__":
    import sys
    seeds = [int(s) for s in sys.argv[1:]] if sys.argv[1:] else [2**i + 3 for i in range(5, 8)]

    results = []
    for seed in seeds:
        result = run_trial(seed)
        print(f"TRIAL: {result}")
        results.append(result)

    mean_supp_eff = sum(result["metric_value"] for result in results) / len(results)
    max_supp_eff = max(result["metric_value"] for result in results)
    support_fraction = sum(1 for result in results if result["conjecture_holds"]) / len(results)

    if all(result["conjecture_holds"] for result in results):
        print(f"RESULT: SUPPORTED mean={mean_supp_eff} std=0.0 support_fraction={support_fraction}")
    elif any(result["metric_value"] > 1.05 for result in results):
        first_failing_seed = next(seed for seed, result in zip(seeds, results) if result["metric_value"] > 1.05)
        print(f"RESULT: FALSIFIED counterexample='max(supp_eff) > s' first_failing_seed={first_failing_seed}")
    else:
        print(f"RESULT: INCONCLUSIVE reason=not_enough_support")

import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def f(x, y):
        return x == y

    M = communication_matrix(f)
    n = len(M)
    P_f = maximal_rectangles(M)
    mu_f = moebius_function(P_f)
    MM_f = total_moebius_mass(mu_f, P_f)
    D_cc_f = disjointness_communication_complexity(f)

    return {
        "metric_name": "log2_MM",
        "metric_value": math.log2(MM_f),
        "instances_tested": 1,
        "conjecture_holds": log2_MM >= D_cc_f / 4 if D_cc_f >= 4 else False,
        "counterexample": "" if (D_cc_f < 4 or log2_MM >= D_cc_f / 4) else f"Counterexample: D^cc(f)={D_cc_f}, log2 MM(f)={log2_MM}"
    }

def communication_matrix(func):
    n = len(next(iter(func.values())))
    M = [[func((i, j), (x, y)) for x in range(n)] for i in range(n)]
    return M

def maximal_rectangles(M):
    def support(row):
        return [j for j, val in enumerate(row) if val == 1]

    P_f = []
    n = len(M)
    for A in range(1 << n):
        rows_A = [i for i in range(n) if (A & (1 << i)) != 0]
        B = set.intersection(*[set(support(M[i])) for i in rows_A])
        if B and all((A & (1 << i)) != 0 for i in rows_A):
            P_f.append((rows_A, list(B)))
    return P_f

def moebius_function(P_f):
    n = len(P_f)
    mu = [[0] * n for _ in range(n)]

    def dfs(i, j):
        if i == j:
            return 1
        if i > j:
            return 0
        mu[i][j] = -sum(mu[i][k] for k in range(i+1, j))
        return mu[i][j]

    for i in range(n):
        dfs(0, i)
    return mu

def total_moebius_mass(mu_f, P_f):
    MM_f = sum(abs(mu_f[i][j]) for i in range(len(P_f)) for j in range(i+1, len(P_f)))
    return MM_f

def disjointness_communication_complexity(func):
    n = len(next(iter(func.values())))
    def partition_number(submat):
        if not submat:
            return 0
        m = len(submat)
        dp = [[0] * (m + 1) for _ in range(m + 1)]
        for i in range(1, m + 1):
            for j in range(i, m + 1):
                dp[i][j] = dp[i-1][j] + sum(func((i-1, k), (x, y)) for x in range(n) for y in range(n))
        return dp[1][m]

    memo = {}
    def memoized_partition_number(submat):
        if not submat:
            return 0
        key = tuple(tuple(row) for row in submat)
        if key not in memo:
            memo[key] = partition_number(submat)
        return memo[key]

    def submatrix(A, B):
        return [[func((i, j), (x, y)) for x in A for y in B] for i in range(n) for j in range(n)]

    def all_subsets(s):
        subsets = []
        for r in range(1 << len(s)):
            subset = [s[i] for i in range(len(s)) if (r & (1 << i)) != 0]
            subsets.append(subset)
        return subsets

    max_partition_size = 0
    for A in all_subsets(range(n)):
        for B in all_subsets(range(n)):
            submat = submatrix(A, B)
            partition_size = memoized_partition_number(submat)
            if partition_size > max_partition_size:
                max_partition_size = partition_size

    return max_partition_size

