            for j in range(i + 1, n):
                if abs(A[j][i]) > abs(A[max_row][i]):
                    max_row = j
            A[i], A[max_row] = A[max_row], A[i]

            # Eliminate non-pivot elements
            for j in range(n):
                if i != j:
                    factor = A[j][i] / A[i][i]
                    for k in range(n + 1):
                        A[j][k] -= factor * A[i][k]

    def characteristic_polynomial(A):
        n = len(A)
        x = Fraction('x')
        det = Fraction(1)
        for i in range(n):
            det *= (A[i][i] - x)
        return det

