    except Exception as e:
        return {
            "metric_name": "secant_variety_order",
            "metric_value": None,
            "instances_tested": n,
            "conjecture_holds": False,
            "counterexample": str(e)
        }
    return {
        "metric_name": "secant_variety_order",
        "metric_value": order,
        "instances_tested": n,
        "conjecture_holds": True,
        "counterexample": ""
