    def min_distance(matroid):
        distances = {}
        for m1 in matroid:
            for m2 in matroid:
                if m1 != m2:
                    distance = sum(1 for x in m1 if x not in m2)
                    distances[(m1, m2)] = distance
                    distances[(m2, m1)] = distance
        return min(distances.values())

