import random
import math
from fractions import Fraction

def gaussian_elimination(matrix):
    n = len(matrix)
    for i in range(n):
        # Find pivot
        max_row = i
        for j in range(i+1, n):
            if abs(matrix[j][i]) > abs(matrix[max_row][i]):
                max_row = j
        matrix[i], matrix[max_row] = matrix[max_row], matrix[i]

        # Eliminate below
        for j in range(i+1, n):
            factor = Fraction(matrix[j][i], matrix[i][i])
            for k in range(n+1):
                matrix[j][k] -= factor * matrix[i][k]

    # Back substitution
    x = [0] * n
    for i in range(n-1, -1, -1):
        x[i] = Fraction(matrix[i][n], matrix[i][i])
        for j in range(i-1, -1, -1):
            matrix[j][n] -= matrix[j][i] * x[i]
    return x

def solve_linear_system(A, b):
    augmented_matrix = [row + [b[i]] for i, row in enumerate(A)]
    solution = gaussian_elimination(augmented_matrix)
    return solution

def min_geometric_invariant(vertices, facets):
    n = len(vertices[0])
    min_dist = float('inf')

    for facet in facets:
        A = []
        b = []
        for vertex in vertices:
            eq = [vertex[i] for i in facet]
            A.append(eq)
            b.append(-eq[facet[-1]])

        try:
            solution = solve_linear_system(A, b)
            dist = sum(x**2 for x in solution) ** 0.5
            if dist < min_dist:
                min_dist = dist
        except Exception as e:
            return float('inf')

    return min_dist

