    # Construct binary tree
    tree = {0: []}
    for i in range(1, 2**n):
        parent = (i - 1) // 2
        tree[parent].append(i)

    # Construct AC^0 circuit
    ac0_circuit_size = sum(len(tree[i]) for i in range(1, 2**n))

    # Calculate automorphism group size
    automorphism_group_size = 2**n

