        result = [0] * (2*n)
        for k in range(2*n):
            sum_val = 0
            for j in range(n):
                sum_val += f[j] * math.cos(math.pi * j * k / n) + f[j+n] * math.sin(math.pi * j * k / n)
            result[k] = sum_val
        return result

    def min_rank_kostant_sheaf(f):
        n = len(f)
        fourier_f = fourier_transform(f)
        rank = 0
        for i in range(n):
            if fourier_f[i] != 0:
                rank += 1
        return rank

