        C = [[0 for _ in range(p)] for _ in range(m)]
        for i in range(m):
            for j in range(p):
                for k in range(n):
                    C[i][j] += A[i][k] * B[k][j]
        return C

    def determinant(A):
        m = len(A)
        if m == 1:
            return A[0][0]
        det = 0
        for i in range(m):
            submatrix = [row[:i] + row[i+1:] for row in A[1:]]
            det += (-1) ** i * A[0][i] * determinant(submatrix)
        return det

    def is_expander(G, n):
        degree_sum = sum(sum(1 for _ in neighbors) for neighbors in G)
        if degree_sum == 0:
            return False
        avg_degree = degree_sum / n
        if avg_degree < 2:
            return False
        max_degree = max(len(neighbors) for neighbors in G)
        if max_degree > 2 * avg_degree:
            return True
        return False

    def geometric_entropy(G):
        n = len(G)
        A = [[0 for _ in range(n)] for _ in range(n)]
