    program = []
    for _ in range(n):
        if random.choice([True, False]):
            program.append('0')
        else:
            program.append('1')
    return program

def construct_semigroup(program):
    semigroup = set()
    current_state = 0
    for symbol in program:
        if symbol == '0':
            current_state = (current_state * 2) % len(program)
        else:
            current_state = (current_state * 3 + 1) % len(program)
        semigroup.add(current_state)
    return semigroup

def local_dimension(semigroup, a, r):
    generators = set()
    for element in semigroup:
        if element not in generators and all(element[i] == generator[i] for i in range(len(generator))):
            generators.add(element)
    return len(generators)

