    def generate_cnf(n):
        clauses = []
        for _ in range(n):
            clause = [random.choice([-1, 1]) * (i + 1) for i in range(n)]
            if sum(clause) != 0:
                clauses.append(clause)
        return clauses

    def resolution_graph(cnf):
        graph = {}
        for i in range(len(cnf)):
            for j in range(i + 1, len(cnf)):
                if any(abs(x) == abs(y) and x * y < 0 for x in cnf[i] for y in cnf[j]):
                    for var in set(cnf[i]) | set(cnf[j]):
                        if var not in graph:
                            graph[var] = []
                        if -var not in graph:
                            graph[-var] = []
                        if j not in graph[var]:
                            graph[var].append(j)
                        if i not in graph[-var]:
                            graph[-var].append(i)
        return graph

    def minimal_rank(graph):
        rank = 0
        visited = set()
        for node in graph:
            if node not in visited:
                queue = [node]
                while queue:
                    current = queue.pop(0)
                    if current not in visited:
                        visited.add(current)
                        for neighbor in graph[current]:
                            if neighbor not in visited:
                                queue.append(neighbor)
                rank += 1
        return rank

    def monotone_circuit_depth(cnf):
        n = len(cnf)
        graph = resolution_graph(cnf)

        def dfs(node, parent):
            nonlocal depth
            if node not in visited:
                visited.add(node)
                for neighbor in graph[node]:
                    if neighbor != parent:
                        dfs(neighbor, node)
                depth = max(depth, len(visited))

        visited = set()
        depth = 0
        for i in range(n):
            dfs(i, None)
        return depth

    n = random.randint(5, 40)
    cnf = generate_cnf(n)
    graph = resolution_graph(cnf)
    rank = minimal_rank(graph)
    depth = monotone_circuit_depth(cnf)

