        return m / 2 + len(pi) * math.log2(m)

    def min_symplectic_tensor_product_rank(tensor):
        n = len(tensor)
        rank = 0
        for i in range(n):
            for j in range(i, n):
                if tensor[i][j] != 0:
                    rank += 1
        return rank

    def permutation_circuit_depth(n):
        return int(n ** math.log2(3 / 4))

